// Writes docs/design/text/loading_quotes_v2.json from the table below and prints counts.
// Row: [index, group, region, speaker, sea, text, attribution, basis]
import fs from 'node:fs';
import path from 'node:path';

const ROOT = 'C:/Users/klimp/OneDrive/Documents/Paradox Interactive/Hearts of Iron IV/mod/zin';
const src = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools/content/data/loading_tips.json'), 'utf8'));

const ML = 'Middle Lands and Aenor', CH = 'Chronicles of the ages', FI = 'Figures of the ages', TE = 'Temples and faiths',
  EL = 'The elves', NO = 'The North Lands', CO = 'The Cold Lands', WE = 'The West Lands', PU = 'The Pupor Isles',
  IS = 'The Islands of the South', SU = 'The Lands of the Sun', DA = 'The Dark Lands', EM = 'The Ember Lands and Mirolon',
  ZO = "Zol's Mistake", EA = 'The East Lands', SO = 'The South Lands', HI = 'Hirolon';

const Q = [
[0, ML, 'Middle Lands', 'peasant', 0, "My grandmother used to say that a crown is gold only on the outside, and that a king who never looks inside his own will never find out how much it weighs.", "Saying of the Vale of Aenor", "The Golden King's love of gold (E)"],
[1, ML, 'Middle Lands', 'proverb', 0, "The old folk say they built Parim beside the Great Lake so that a king looking out of his window would never forget where his bread was grown.", "Proverb of the lake-country", "Parim and the Great Lake heartland (W, E)"],
[2, ML, 'Middle Lands', 'peasant', 0, "Plough the old grave-fields deep and keep your grumbling to yourself, because the wizard lifted the Necromancer's curse from that ground long ago, and it has given good barley ever since.", "Ploughmen's saying, Middle Lands", "Varner lifted the curse of the grave-fields (E deed, P dates)"],
[3, ML, 'Middle Lands', 'proverb', 0, "The Charters call every dominion a partner of the crown, which is a handsome word, though I notice it is still the crown that does the asking and the partners that do the paying.", "Grumble of the Concord dominions", "Charters of Parim (P)"],
[4, ML, 'Middle Lands', 'trader', 0, "You can buy a judgeship at the Golden Court in Rasthel and sell it again by Aurlan, and if you are clever you will turn a profit on the justice in between.", "Market jest of Parim", "Sale of offices (E); months named for the twelve (P, calendar.md)"],
[5, ML, 'Middle Lands', 'soldier', 0, "The court gave us new banners for the jubilee and no new boots, so when the levy is called we shall march to the border looking very fine and limping.", "Saying of the Aenoran levies", "The long peace (E); a court that neglects its hosts (P, Aenor spec)"],
[6, ML, 'Middle Lands', 'proverb', 0, "Aen had hundreds of sons, which is why every lord in the Middle Lands can show you a roll proving his royal blood, and why not one of them can show you a roll that makes him king.", "Saying of the heralds of Parim", "Aen's hundreds of sons (E); competing branches (P)"],
[7, ML, 'Middle Lands', 'woodsfolk', 0, "We hear the Baelim long before we see them, a low sound under the trees like a cart on a far road, and when we hear it we step off the path and wait, because they will not step off it for us.", "Saying of the Selen rangers, Aenor Forest", "The walking tree people of Aenor Forest (E people, owner 24 October 2026; P name Baelim, Middle Lands dossier)"],
[8, HI, 'Hirolon', 'giant', 0, "Men come up into our hills to ask what we remember, and we tell them, and then they hurry down again to write it on a skin that will rot long before the cairn does.", "Saying of the giants of Hirolon", "Hirolon giants (E); cairn-faith (P)"],
[9, ML, 'Middle Lands', 'woodsfolk', 0, "If you ask an ent of Kilinti the way through the forest he will tell you truly and in full, but bring a loaf and a blanket, because the telling takes a good deal longer than the walk.", "Saying of the Kilinti woodcutters", "Ents of Kilinti (E)"],
[10, ML, 'Middle Lands', 'proverb', 0, "A rider of Hunhun will tell you that he owns three things in this world, his horse, his word and the sky over the steppe, and that he would sooner lose the first than the second.", "Horse-lords' saying, Hunhun", "Riders of Hunhun (E); the Horse-Oath (P)"],
[11, ML, 'Middle Lands', 'priest', 0, "On the first of Irumas every smith in the Vale lets his forge go cold at dawn and lights it again from the Anvil-Priest's fire, and anyone who wants a horseshoe before noon gets a blessing instead.", "Custom of the smiths of the Vale of Aenor", "Irumas and the Kindling of the Forges (P, pantheon.md 3.10)"],
[12, ML, 'Middle Lands', 'inscription', 0, "Pass in peace, traveller, and open your packs to the toll-men, for this road runs through the mountains by leave of two peoples and belongs to neither of them.", "Inscription over the gate of Kingson", "The Great Wall of Aenor, a natural range (E); the Kingson Pass and the Accord of the Passes, 4A 96 (P)"],
[13, WE, 'West Lands', 'dwarf', 0, "We cut the stone for every guild-hall in Kradlon and the guild masons lay it, and when a hall falls down the guilds blame the stone, which is how you know they have never cut any.", "Proverb of the dwarves of the Herlitz Mountains", "Dwarves hold the great ranges of the West (E, owner 24 October 2026); dwarf-cut stone for the guild halls (P, West Lands dossier)"],
[14, ML, 'Middle Lands', 'dwarf', 0, "We sell iron to the men of Kingson by the honest pound and to the elves by the elvish pound, which is the same weight at twice the price, and neither has ever complained to our faces.", "Proverb of the dwarves of Kunhrim", "Dwarves hold the Great Wall range (E, owner 24 October 2026); dwarves dislike elves (E, dwarf card); Kunhrim iron sold at Kingson (P)"],
[15, ML, 'Middle Lands', 'custom', 0, "When the granary of the House of the First Light is full they ring the bell at dawn, and in a lean year the bell stays silent, so every street knows how the harvest went before the bailiff does.", "Custom of the Houses of the First Light", "Houses keep the grain stores (P)"],
[16, CH, 'Middle Lands', 'scholar', 0, "A scribe of Parim writes Aen, First of His Name, and never First of Men, because men had kings for thousands of years before him and the University will not let anyone forget it.", "Rule of the scribes of Parim", "Aen, First of His Name (E); scribes' rule (P)"],
[17, CH, 'Middle Lands', 'chronicler', 0, "For centuries the kingdoms of men fought over whether there should be one crown or many, and it was Aen who settled the matter in the end, at the cost of most of the others.", "The Chronicle of Aoaz: the First Age", "The War of Men (E)"],
[18, CH, 'West Lands', 'chronicler', 0, "When Aenor's ships came to the western shores there were already people living there, and that, when you come down to it, is the whole of a quarrel that has lasted four ages.", "A western reading of the Chronicle", "Aenor's wars in the West (E)"],
[19, CH, 'Ember Lands', 'chronicler', 0, "In the First Age the south seemed to guard itself, for storms closed its coasts, and the few men who did get ashore found a heat that killed them faster than any army could.", "The Chronicle of Aoaz: the First Age", "Ember Lands storms and heat (E)"],
[20, CH, 'North Lands', 'chronicler', 0, "The Leren fought beside Aen as allies and never as his subjects, and the Annals of Sonargur have taken care to repeat the point in every reign since, in case a king of Aenor should forget it.", "The Annals of Sonargur", "The Leren were Aenor's allies in the First Age, never subjects (E, North Lands dossier)"],
[21, CH, 'All Aoaz', 'chronicler', 0, "Men, elves, dwarves, giants and spirits once stood together under King Edran's banners, and no age since has managed it again, though the scholars of Parim have spent many winters arguing how he did it.", "The Chronicle of Aoaz: the Grand Alliance", "The Grand Alliance (E)"],
[22, CH, 'All Aoaz', 'chronicler', 0, "The Grand Alliance won at Dardan, and the clerks who counted the dead afterwards gave up long before they reached the end, for the field was a wasteland and every kingdom of the Alliance had sons buried in it.", "The Chronicle of Aoaz: the First Age", "Battle of Dardan (E)"],
[23, CH, 'Ember Lands', 'chronicler', 0, "The spirits did not kill Volgan when they beat him; they stripped him of his strength and threw him into the Void, and any warden of Mirolon will tell you that what is thrown out can find its way back.", "A commentary on the Chronicle", "Banishment to the Void, later return (E)"],
[24, CH, 'Ember Lands', 'chronicler', 0, "King Edran won the war and could not leave well alone, for he would not stop at Dardan, and it was the elves who paid for his campaign in the Ember Lands with their dead.", "The Chronicle of Aoaz: the First Age", "Edran's failed Ember Lands campaign (E)"],
[25, CH, 'All Aoaz', 'chronicler', 0, "They called the Second Age the Long Grief, and so it was, yet in those years the farmers learned to keep seed through a bad winter, the healers to stop a plague and the builders to raise walls that held.", "The Chronicle of Aoaz: the Second Age", "Second Age advances (E); the name Long Grief (P)"],
[26, CH, 'All Aoaz', 'chronicler', 0, "King Edran, the greatest king since Aen, came home from all his wars and died in his bed of a sickness that no physician of his court could cure.", "The Chronicle of Aoaz: the Second Age", "Edran died of disease (E)"],
[27, CH, 'Magical Lands', 'chronicler', 0, "When the Necromancer came the elves did not, and the men of Aenor called it betrayal, though the elves, who had buried their own dead in King Edran's war, called it remembering.", "The Chronicle of Aoaz: the Second Age", "The Elven Refusal (E)"],
[28, CH, 'All Aoaz', 'chronicler', 0, "In the last centuries of the Second Age the Necromancer's war came from within, and orc and goblin hosts climbed out of the deep places in lands that had thought themselves safe.", "The Chronicle of Aoaz: the Second Age", "Elzon's war from within; hosts rising from deep underground (E, Second Age Canon Register)"],
[29, CH, 'Middle Lands', 'chronicler', 0, "The Second Age was the longest of the four, two thousand one hundred and thirty-three years, and it ended in the last days of its last year, when the Necromancer took Aenor.", "The Chronicle of Aoaz: the Second Age", "The Second Age lasted 2,133 years and ended with Elzon's conquest (E)"],
[30, SO, 'South Lands', 'trader', 0, "The pass-lords of Miaed charge a toll at the top of the Hardtmuth road and another at the bottom, and they will tell you with a perfectly straight face that it is only fair, since the road goes both ways.", "Saying of the desert caravans", "Miaed and its pass-lords on the Hardtmuth passes (P, South Lands dossier)"],
[31, CH, 'Middle Lands', 'chronicler', 0, "Elzon did not fade like his dead and did not sleep as the Old Gods are said to; when his end came he died, wholly and for good, and the Chronicle has never had to correct the entry.", "The Chronicle of Aoaz: the Third Age", "Elzon's permanent death (E); conflicting accounts of the Old Gods (E)"],
[32, CH, 'Middle Lands', 'chronicler', 0, "When the Necromancer fell, the faithful say, the Deliverer stood between the people and the ruin, and the temples were full that day and have not been empty since.", "The Chronicle of Aoaz: the Fourth Age", "The Deliverer acclaimed at Elzon's fall (E, public)"],
[33, CH, 'Middle Lands', 'chronicler', 0, "Harion of Selen took up a crown that had waited twelve hundred years for a head, and the Annals note with some surprise that it still fitted a good man.", "The Annals of Parim", "A good king restores Aenor (E); Harion (P)"],
[34, CH, 'Middle Lands', 'chronicler', 0, "4A 96: the elves and the restored crown agreed at Kingson that the elves should keep the eastern forts of the passes and the crown the western, and that the crown should take the tolls, which pleased both.", "The Annals of Parim", "The Accord of the Passes (P, replacing the Wall Accord)"],
[35, CH, 'Middle Lands', 'chronicler', 0, "4A 1000: Parim kept the feast of a thousand years of peace, envoys came from every coast of Aoaz to drink the king's health, and the Annals record with pride that not one of them came armed.", "The Annals of Parim", "The Thousand-Year Jubilee (P)"],
[36, CH, 'East Lands', 'chronicler', 0, "In the First Age the kings of the East did not all choose the same side, for some marched for Volgan and some did not, and the courts of the East still remember very well which was which.", "The Chronicle of Aoaz: the First Age", "Eastern kings divided in Volgan's war (E, First Age)"],
[37, CH, 'North Lands', 'chronicler', 1, "4A 1744: the fishermen who came in this spring speak of black ships among the islands of the Kusmeel, and the harbour-master has had their tale written down, though he does not believe a word of it.", "The Harbour Rolls of Sonargur", "Black ships rumour (P; disputed, V10)"],
[38, CH, 'West Lands', 'chronicler', 0, "4A 1745: King Herlic of Gunwyn and the wardens of Girdon swore the Truce of the Grey Ford at the stone, and the West has been quiet since, though the annalist notes that he has bought a new sword.", "The Annals of Gunwyn", "Truce of the Grey Ford (P)"],
[39, SO, 'South Lands', 'trader', 0, "Caravan men of the Sun Desert say the dunes run south until the sand turns to ash, and that beyond lies a country of fire no chart shows, and there they stop the story and talk about the price of salt.", "Saying of the Sun Desert caravans", "The lands south of the South Lands, home of devils and demons, known by name only (E, owner 24 October 2026)"],
[40, FI, 'Middle Lands', 'ruler', 0, "I mean to make one crown of all these crowns, so that the mothers of the Middle Lands may stop burying their sons for the sake of the rest.", "Words the heralds give to Aen, First of His Name", "Aen's unification (E); speech (P)"],
[41, FI, 'All Aoaz', 'court', 0, "Let every banner keep its own colours, for we march together and not as one, and no lord shall be asked to fold his standard under another's in order to fight beside him.", "Preamble of the Charter of Free Banners", "Charter of Free Banners (P); Edran's alliance (E)"],
[42, FI, 'West Lands', 'soldier', 0, "She asked that her name be written in the muster before she marched, and it was written, and she went to Dardan with the clans, and the banner of Gunwyn did not turn that day or any day after.", "Song of Taryn's banner, Gunwyn", "Western banners at Dardan (E); Taryn (P)"],
[43, PU, 'Pupor Isles', 'proverb', 0, "When no road could reach the host at Dardan the islands fed it, and the islanders will remind you of it at every table they set, usually while they are passing you the bread.", "Island saying of Senra's people", "Island supply of the Alliance (E); Senra of the Pupor Isles (P)"],
[44, FI, 'Magical Lands', 'elf', 0, "A healer does not ask which banner a wound was made under, and if you are too proud to be tended beside your enemy, you are welcome to bleed outside.", "Tavriel of the Magical Forest", "Second Age proposed character (P)"],
[45, FI, 'Middle Lands', 'priest', 0, "When we lay the raised dead down again we speak to them gently, because the poor things meant no harm and only wanted to sleep, and it was someone else who would not let them.", "Saying of the Lantern Chain's healers", "Varner's work against the curse of the dead (E); the Lantern Chain (P)"],
[46, FI, 'Middle Lands', 'goblin', 0, "Our king was only a hobgoblin once, like any other, but he ate well and grew, and now he is very big and very wise, and anyone who thinks the second does not follow from the first can tell him so.", "Saying of the warrens of Glimik", "The hobgoblin king, a hobgoblin who grew very big (E, card); he rules his own realm only (E, owner 24 October 2026); Glimik (P)"],
[47, SU, 'Lands of the Sun', 'elf', 0, "Our king led the host to Dardan and remembers it still, and yet the Keepers write down every word he says, because they reckon the roll will outlast even him.", "Keepers of the court of Gala", "Lorien, king of the Gala elves, remembers Dardan (E); the Keepers (P)"],
[48, SU, 'Lands of the Sun', 'elf', 0, "Do not frighten your people with prophecy, for a frightened people will work very hard to make it come true.", "Proverb of the court of Gala", "The Mirror Vigil and its distrust of prophecy (P)"],
[49, SO, 'South Lands', 'peasant', 0, "The oasis keepers tell every traveller never to sleep in a cave mouth that is warmer than the rock around it, because the sand golems lie there, and they are very slow to forgive being woken.", "Saying of the oasis keepers, Sun Desert", "Sand golems in the desert caves (E, card 7; P placement, South Lands dossier)"],
[50, HI, 'Hirolon', 'giant', 0, "We treat with the king in Parim as one crown with another and have never taken a charter from him, because a promise that needs a scribe to hold it was never much of a promise.", "Saying of the High Chief's hall, Hirolon", "Hirolon, a sovereign giant kingdom that treats with Aenor (E, owner 24 October 2026); the Cairn Treaty (P)"],
[51, FI, 'Middle Lands', 'court', 0, "The seals of the kingdom are heavy, Your Majesty, and I am glad to carry them for you, so that you need never trouble yourself with what they are pressed upon.", "Merovan, Keeper of the Seals", "Merovan holds the seals (P name, E role)"],
[52, CO, 'Cold Lands', 'goblin', 0, "The sun makes a goblin sleepy, which is why the warrens of Glimkit leave the whole day to the big folk, since it is plainly all they are fit for.", "Saying of the warm valleys of Glimkit", "Goblins hold sheltered valleys of the southern Cold Lands (E, owner 24 October 2026); the sun makes goblins drowsy (E, card); Glimkit (P)"],
[53, FI, 'Middle Lands', 'soldier', 0, "I have told the court every spring for ten years that a host which drills only for the king's birthday will fight like one, and every spring they thank me and order new plumes.", "Marshal Corwen Hornan of Aenor", "Aenor's honest marshal (P)"],
[54, FI, 'Middle Lands', 'soldier', 0, "The court companies of the Lost Cause wear the badge on their best coats, and my frontier companies wear it on their old ones, because they had to earn it in the mud.", "Lord-Commander Tarec Belurith", "Lost Cause frontier companies are real (E direction)"],
[55, FI, 'Middle Lands', 'scholar', 0, "The University has taught the learned art for centuries and has given the Middle Lands exactly one wizard whom everybody has heard of, which the masters find a good deal more awkward than Bastian does.", "Jest of the students of Parim", "Bastian, a living wizard of men famous in the Middle Lands (E, owner 24 October 2026); the University (P)"],
[56, HI, 'Hirolon', 'peasant', 0, "We graze our sheep on the giants' eastern slopes for one fleece in ten, and in all the years my family has paid that rent, no giant has ever once miscounted.", "Saying of the herders of the Grano slopes", "Hill-herders of men on Hirolon's eastern slopes (P, Hirolon dossier)"],
[57, FI, 'Middle Lands', 'court', 0, "Selen loves the crown the way the forest loves the road, which is to say we let it through and keep an eye on it the whole way.", "First Warden Daeric Svenlor of Selen", "Selen's pride (P)"],
[58, HI, 'Hirolon', 'small folk', 0, "The giants keep the passes and we keep the barley, and on a good evening we keep the giants as well, in ale, which is a fair bargain by anybody's reckoning.", "Saying of the small folk of Tirlan", "The small folk under Hirolon's protection (E people, owner 24 October 2026; P Tirlan, Hirolon dossier)"],
[59, TE, 'Magical Lands', 'faithful', 0, "A lamp in the window and a loaf on the table for whoever is on the road tonight: that is all the Deliverer has ever asked of a house, and it is not much to ask.", "Ilvane, High Confessor of the Deliverer", "Public worship (E); Ilvane (P)"],
[60, TE, 'Magical Lands', 'faithful', 0, "Our three valleys have no army to speak of and the busiest roads in Aoaz, and I would not change either, since pilgrims eat a great deal more than soldiers and pay for what they eat.", "Abbot-Steward Lozan Heron of the Worshipdom", "The Worshipdom's valleys and pilgrims (P, public face)"],
[61, EL, 'Magical Lands', 'elf', 0, "A decision of the houses is judged as one judges a young tree, by what it shelters when those who planted it are long gone.", "First Speaker Lusiel Velakorin of the Magical Forest", "Elected houses of the Magical Forest (P constitution)"],
[62, EL, 'Magical Lands', 'elf', 0, "No keeper of the roosts ever says my dragon; we say the dragon who allows me to stand near, and those who forget the difference seldom get the chance to forget anything else.", "Perlan, Warden of the Dragon Roosts", "Elves command dragons (E); office (P)"],
[63, EL, 'Magical Lands', 'elf', 0, "Men often ask why we did not come when the Necromancer marched on Aenor, and we answer that we had come once already, for King Edran, and were still burying what that cost us.", "Loremaster Aenwe Lozari of the Magical Forest", "The Elven Refusal (E); speaker (P)"],
[64, FI, 'North Lands', 'ruler', 0, "We were not humiliated in Parim in 4A 1716, whatever the Golden Court likes to say; we were taught the price of a toll, and we have been studying the lesson with great care ever since.", "King Ferlin III of Lerendor and Lerendor's North", "The toll quarrel (P); one crown of Lerendor and Lerendor's North (E one crown, P name)"],
[65, FI, 'Cold Lands', 'ruler', 0, "A queen of the Cold Lands rules ice, wind and men, and she learns early that the men are the only ones of the three who ever listen to her.", "Queen Vaestia of Coldor", "Coldor's crown (P)"],
[66, FI, 'West Lands', 'ruler', 0, "I signed the truce at the Grey Ford with my left hand, and my right stayed on my sword hilt the whole time, more out of habit than ill will, I assure you.", "King Herlic of Gunwyn", "Truce of the Grey Ford (P)"],
[67, FI, 'West Lands', 'court', 0, "The law of Gunwyn binds the king just as it binds the shepherd, and I have noticed over the years that the shepherd finds this a good deal more comforting than the king does.", "Lawspeaker Ilurda of Gunwyn", "Gunwyn's lawspeaker (P)"],
[68, FI, 'West Lands', 'soldier', 0, "Swear the truce at the stone if you must, but keep your blade greased, because the stone forgives nothing, and neither does the Lawspeaker, and the clans of Girdon know it as well as we do.", "Thane Datid Werlen of Gunwyn", "Truce of the Grey Ford (P); Gunwyn oath-stones (P)"],
[69, FI, 'East Lands', 'ruler', 0, "A caravan is a kingdom that happens to be moving, and mine moves rather faster than the Prince of Postondoroth's, which is the whole of our quarrel in a sentence.", "King Esiurth II of Noris", "Noris and the caravan roads (P)"],
[70, FI, 'East Lands', 'ruler', 0, "Noris owns the desert, and I grant him that freely, but we own the people who have to cross it, and they settle their bills on time.", "Prince Cereos of Postondoroth", "Stabilo's rivalry with Noris (W, P)"],
[71, FI, 'Dark Lands', 'dark power', 0, "A warking who cannot win a fight will not keep his crown for long, and a warking who must fight every day to keep it has lost it already and simply not noticed.", "Warking Gorduth of Cocanoor", "Goldoroth (W); ruler (P)"],
[72, FI, 'Ember Lands', 'ruler', 0, "Mirolon has never asked the north to love us, only to look south once a year and see what we see every night from the beacon towers.", "High Warden Maeric of Mirolon", "Mirolon watches the south (E rivalry; P ruler, Mirolon tree)"],
[73, FI, 'Ember Lands', 'court', 0, "I carried the warning to Parim in autumn with the dust of the southern road still on my cloak, and the court thanked me very kindly, fed me well and sent me home.", "Envoy Hessa Mencnor of Mirolon", "The envoy of 4A 1736 (P)"],
[74, FI, 'Ember Lands', 'soldier', 0, "Watch the dust on the southern road, lad, because a scout's eyes will lie to you about how many are coming and how fast, but the dust never does.", "Captain Bennar of the Passes", "Mirolon's scouts (P)"],
[75, TE, 'Middle Lands', 'faithful', 0, "He stood between us and the ruin when the Necromancer fell, and so we keep a lamp lit in every window, that he may see we have not forgotten.", "The Litany of the Deliverer", "Public worship of the Deliverer (E)"],
[76, TE, 'Magical Lands', 'faithful', 0, "Deliverance for those who have fallen, protection for those who keep faith, and renewal for the land that feeds us all.", "Blessing of the pilgrim-houses of the Zilin Hills", "The Deliverer, New God of Deliverance, Protection and Renewal, as the faithful hold (P); the Worshipdom's pilgrims (P, public face)"],
[77, PU, 'Pupor Isles', 'proverb', 0, "The islanders say their speech and the speech of Gunwyn were brothers once, and that Gunwyn went inland and grew fat on cattle while the islands stayed lean and kept the better words.", "Saying of the Pupor Isles", "Tritonic, a Boreal tongue kin to Gunwyn (P, languages spec and West Lands dossier)"],
[78, TE, 'Magical Lands', 'faithful', 0, "Come to Zilin with empty hands, the pilgrims say, and you will go home with a blessing, a full belly and a letter to carry for some stranger in your own town.", "Pilgrims' saying of the Zilin Hills", "Pilgrims and couriers of the Worshipdom (P, public face)"],
[79, TE, 'East Lands', 'priest', 0, "In the Hall of Scales at Postondoroth a false weight is reckoned a worse crime than a broken head, because a head will mend in a month and a merchant's name never does.", "Saying of the Weighers of Stabilo", "The Creed of the Honest Scale (P, world bible section 4)"],
[80, TE, 'Middle Lands', 'peasant', 0, "Rain for the barley, a priest for the fever and a lamp for the road, my mother used to say, and anyone who has all three and still grumbles about the tithe deserves to pay it twice.", "Peasants' saying of the Middle Lands", "The Lamp and the Furrow, the folk faith of the twelve (P); public worship (E)"],
[81, TE, 'Cold Lands', 'priest', 0, "In the Long Dark every house of the clan lets its own fire go out and comes to the clan fire to light it again, so that no family in the Cold Lands is ever left alone with its cold.", "Custom of the Winter Hearth", "The Winter Hearth and the fire-keepers (P, world bible section 4)"],
[82, PU, 'Pupor Isles', 'proverb', 1, "The wreck-right lords of the outer arc pray every autumn for gales, though they take care to pray quietly, and the chart-houses of Adel, who live by keeping ships off those rocks, do not speak to them.", "Saying of the Pupor Isles", "Wreck-right lords and chart-houses of the Pupor Isles (P, Campaign of 4A 1748 and Pupor Isles dossier)"],
[83, TE, 'North Lands', 'peasant', 0, "Half the priests in Sonargur will tell you the Old Gods are dead and the other half that they only sleep, and the market wives, who have heard both sermons, keep a lamp lit either way.", "Saying of the Leren coasts", "Conflicting accounts of the Old Gods (E)"],
[84, TE, 'North Lands', 'proverb', 0, "The priests of the north say that of all the Old Gods only Zol dwells in Aoaz, and the old women of the strait add that this is one more than anybody would have chosen.", "Saying of the Leren strait", "Zol is the only Old God in Aoaz (E)"],
[85, TE, 'Ember Lands', 'priest', 0, "A king who prays to Kerun for conquest is wasting his breath, the Watch-Chaplains say, because Kerun keeps the walls of the weak and has never once helped anyone to take a wall that was not his.", "Saying of the Watch-Chaplains of Mirolon", "Kerun, New God of protection, and no god of conquest (P, pantheon.md sections 1 and 3.7); Mirolon's beacons as his holy site (P)"],
[86, SO, 'South Lands', 'priest', 0, "A well shared makes kin and a well sealed makes enemies for seven generations, as the well-wives of the Noris desert teach every child old enough to carry a jar.", "Teaching of the Well-Oath", "The Well-Oath of the Noris desert (P, world bible section 4)"],
[87, DA, 'Dark Lands', 'craftsman', 0, "Miners in the Dark Lands say there are spirits so far down under the mountains that they have never seen the sun, and the foremen keep a rope tied to the youngest lad, just in case he finds one.", "Miners' saying of the Dark Lands", "Damned Spirits deep underground (E)"],
[88, IS, 'Islands of the South', 'priest', 0, "When a fever leaves a house the Bowl-Bearers of Sulethe break a bowl on the threshold, and the children of the village come running for the pieces, because a shard of a fever-bowl is the best luck there is.", "Custom of the spring-houses of the southern islands", "Sulethe's rites, strongest among the southern islanders (P, pantheon.md 3.2)"],
[89, TE, 'North Lands', 'priest', 0, "In the Free Crowns the Lamp-Mother puts out every fire in the village on the last night of Sulethe and lights them all again at dawn from the common hearth, so that no house begins the year alone.", "Custom of the Free Crowns of the North", "Lumae's Lamp-Lighting, kept in the Free Crowns of the North (P, pantheon.md 3.3)"],
[90, DA, 'Dark Lands', 'priest', 0, "On the Night of Names the Name-Readers of Dondor read out every name in the roll of the dead, and nobody leaves before the end, because nobody wants a grandmother read to an empty hall.", "Custom of the Name-Readers of Gaelor, Dondor", "Gaelor and the Night of Names (P, pantheon.md 3.11)"],
[91, EL, 'Magical Lands', 'elf', 0, "In the Magical Forest the houses vote and the First Speaker serves, and they reckon a precedent young until it has stood a hundred years and a habit young until it has stood a thousand.", "Saying of the houses of the Magical Forest", "Elected houses of the Magical Forest (E)"],
[92, EL, 'Magical Lands', 'elf', 0, "Men ask why we keep the passes, and we tell them that we kept our distance long before any fort was built in the mountains, and that the forts only made it easier for men to see.", "An elder of the Magical Forest", "The Great Wall of Aenor, a natural range (E); the elves keep the eastern forts of the passes (P, Accord of the Passes)"],
[93, EL, 'Magical Lands', 'elf', 0, "Herrodon and Andos Enda have been quarrelling for so long that their grudges have married and had grandchildren, and the grandchildren have quarrels of their own.", "Saying of Nolorim", "Herrodon and Andos Enda rivalry (W)"],
[94, EL, 'Magical Lands', 'elf', 0, "Nolorim keeps the high passes and sends no word to anyone about what it sees there, and the other houses have learned over the centuries to read a great deal into the silence.", "Saying of the Magical Lands", "Nolorim guards the passes (E name, P role)"],
[95, EL, 'Middle Lands', 'soldier', 0, "Only the elves can call the dragons, but every few years some young lord rides up to our gate with a saddle made for one, and we let him through, and we keep the saddle when it comes back down without him.", "Saying of the gate-wardens of Kingson", "Elven powers command dragons (E)"],
[96, EL, 'Magical Lands', 'court', 0, "The elves were never conquered, not even by the Necromancer, and they mention it seldom, though an envoy soon learns that they never mention it by accident.", "Saying of Aenoran envoys", "The elves were never conquered (E)"],
[97, EL, 'Magical Lands', 'elf', 0, "In the worst years of the Third Age the wizard and his small purple servant walked our roads, and wherever the wizard went the dead lay down again and stayed down.", "As the elves of the Magical Forest remember Varner", "Varner and Golbran in the Third Age (E)"],
[98, EL, 'Magical Lands', 'elf', 0, "Varner never once asked to be thanked, so the elves thank him every spring, at length and rather loudly, in case he happens to be listening.", "Custom of the Magical Forest", "Varner's lasting influence (E); custom (P)"],
[99, EL, 'Magical Lands', 'elf', 0, "Walk softly in the Mushroom Forest, because the mycids feel every footstep through the floor of it, and they are slow to forget a heavy one.", "Saying of the rift shore", "Mycids of the Mushroom Forest (E)"],
[100, NO, 'North Lands', 'proverb', 0, "When Lerendor and Lerendor's North were joined under one crown the old wives of Sonargur called it a good match, since the bride brought snow and the groom brought harbours and each had what the other lacked.", "Saying of Sonargur", "Union of the Leren crowns (E one crown, P date); Lerendor's North, the snow country of the west (P name)"],
[101, NO, 'North Lands', 'court', 0, "We thank our good cousin of Lerendor for his letter on the strait dues, and we have read it twice with great attention, once for its courtesy and once to see whether the figures improved.", "From a letter of the Golden Court to Sonargur", "The toll quarrel over the strait dues (P); the Treaty of the Narrow Strait (P)"],
[102, NO, 'North Lands', 'woodsfolk', 0, "Tolvael bows to no crown and sells its timber to all of them, and its foresters will tell you that no tree has ever once asked who was buying it.", "Saying of Tolvael", "Tolvael's timber (P)"],
[103, NO, 'North Lands', 'proverb', 0, "Molot and R'en sit between the two masters of the strait, and like all small crowns they have learned to smile in both directions at once without straining their necks.", "Saying of the Free Crowns", "Molot and R'en (E names)"],
[104, NO, 'North Lands', 'proverb', 0, "The dwarf goblins of the Leren hills are neither dwarves nor goblins, as they will tell you at length, and the quickest way out of one of their halls is to ask which of the two they are nearer.", "Saying of the Leren uplands", "Dwarf goblins, a people of their own in the hills near Lerendor (E, owner 24 October 2026)"],
[105, CO, 'Cold Lands', 'proverb', 0, "In the Cold Lands a stranger at the door is given a seat by the fire and a bowl before anyone asks his name, and the questions can wait until the thaw.", "Hospitality law of the Cold Lands clans", "Cold Lands clans (E); custom (P)"],
[106, CO, 'Cold Lands', 'proverb', 0, "Coldor has one crown for the whole frozen interior, and the warlords of Melkgard have one answer to it, which they give from behind their black forts every time anyone asks.", "Saying of Fandanar", "Coldor and Melkgard (W rivalry; P name Melkgard, Cold Lands dossier)"],
[107, CO, 'Cold Lands', 'proverb', 0, "Every clan of the Cold Lands has refused some king or other in its time, but I have yet to meet the clan that refused the winter.", "Saying of the Coldor clans", "Cold Lands peoples (E)"],
[108, CO, 'Cold Lands', 'trader', 0, "The traders of Mp'E will tell any newcomer about the silent castle above the town, where a green light burns on clear nights, and then they will sell him a sledge pointed the other way.", "Traders' tale of Mp'E", "Castle of Yeldenne above Mp'E (E); travellers' tale (P)"],
[109, CO, 'Cold Lands', 'trader', 0, "The yeti will trade you furs for salt and the way through the passes for your silence, and of the two bargains the second is much the better, so take it.", "Saying of the ice road", "Yeti Lands (E)"],
[110, CO, 'Cold Lands', 'giant', 0, "We lay a stone on the cairn for every winter, and the stones are cold and the winters were colder, and that is why the young men of the south think we never laugh.", "Saying of the ice giants of Nivaros", "Nivaros ice giants (E people; P name, Cold Lands dossier); the Cairn-Faith (P)"],
[111, CO, 'Cold Lands', 'proverb', 0, "The Cold Lands run off the edge of every chart in Aoaz, and the chart-makers of Fandanar are honest men, so where they stop knowing they simply stop drawing.", "Saying of Coldor's ports", "The Cold Lands reach off the map (E)"],
[112, WE, 'West Lands', 'proverb', 0, "Aenor calls it discovery and we call it what happened to our grandfathers' grandfathers, and both of us have been saying so for four ages without either one of us giving way.", "Saying of the Gunwyn clans", "Aenor's wars in the West (E)"],
[113, WE, 'West Lands', 'trader', 0, "The guild-halls of Kradlon swear their contracts on the guild book and not on any god, because a god may forgive a man and the book never has.", "Saying of the Kradlon guilds", "The Guild Halls (P, world bible section 4)"],
[114, WE, 'West Lands', 'proverb', 0, "Fifty years of war and then one truce at the Grey Ford, and in the West we call that a short quarrel, so you may judge for yourself what we call a long one.", "Saying of the Girdon wardens", "Gunwyn and Girdon wars (E rivalry, P dates)"],
[115, WE, 'West Lands', 'trader', 0, "A clan will forgive a debt, a feud and a bad harvest if you give it time, but no clan of the West has ever been known to forgive a toll.", "Saying of the Corogon traders", "Western resentment of Aenoran tariffs (P)"],
[116, WE, 'West Lands', 'soldier', 0, "The Buldor companies will fight for anyone who asks, and they fight well, but they have never once fought for nothing, and they would be insulted if you suggested it.", "Saying of the West Lands", "Buldor companies (E people)"],
[117, PU, 'Pupor Isles', 'proverb', 0, "On the Pupor Isles a man may own a whole island and still not have soil enough to bury his father in, which is why the islanders grew rich on knowledge instead of land.", "Saying of the Pupor Isles", "The Pupor Isles, poor in land and rich in knowledge (P, Pupor Isles dossier)"],
[118, PU, 'Pupor Isles', 'trader', 1, "We charted every reef in these waters and sold the charts to every crown in Aoaz, and each crown believes it bought the only good copy, which is why we are so polite to all of them.", "Chart-makers' saying of Adel", "Pupor charts (P)"],
[119, IS, 'Islands of the South', 'proverb', 0, "When the old tales of men grow too old for any man to explain, the islanders say, carry them to Gala, because the elves there will remember what we have forgotten.", "Saying of the Islands of the South", "The islanders' saying (chronicle detail)"],
[120, IS, 'Islands of the South', 'priest', 0, "At the shrine beneath the tide the tally-keepers sing a name that none of them understands, and they sing it with great care, because the islanders say the name is needed.", "Saying of Enhis Is Rond", "The shrine that repeats a forgotten name (P); the Wave-Tally (P)"],
[121, IS, 'Islands of the South', 'proverb', 0, "Each island counts its dead as waves on the reef, so a child of the south learns to count on them, and the first sum most of us ever did was a sum of our grandmothers.", "Saying of the tally-caves of Kamu Lamo", "The Wave-Tally (P, world bible section 4; Islands of the South dossier)"],
[122, IS, 'Islands of the South', 'proverb', 1, "A stranger the sea throws onto our beach is fed and given a mat, and if the sea throws him back to us a second time, the elders say he is plainly meant to be family.", "Hospitality saying of Howan", "Island hospitality (P)"],
[123, SU, 'Lands of the Sun', 'proverb', 0, "A Sunhot elf stands taller than a man on horseback and speaks more softly than a child, and the Sunfolk say a strong hand never had any need of a loud voice.", "Saying of the Goodin Sunfolk", "Sunhot elves' height and peace (E)"],
[124, SU, 'Lands of the Sun', 'proverb', 0, "Where the strong are gentle the weak can sleep sound, and the Sunfolk have never needed a wall to keep the Sunhot from them, nor the Sunhot one to keep out the Sunfolk.", "Saying of the Goodin Sunfolk", "Sunhot elves (E); Goodin Sunfolk (P)"],
[125, SU, 'Lands of the Sun', 'elf', 0, "The host of Gala marched to Dardan for a king it hardly knew, and Gala has never regretted Dardan, though it has had a long time to regret what King Edran did afterwards.", "Saying of the court of Gala", "Gala at Dardan; Edran's folly (E)"],
[126, SU, 'Lands of the Sun', 'proverb', 0, "In the Lands of the Sun nothing is settled before noon, and the Lands of Light always speak last, so the other realms have learned to bring their dinners to the council.", "Saying of the noon court", "The Lands of Light (W); the noon court (P)"],
[127, SU, 'Lands of the Sun', 'elf', 0, "Pilgrims who come to rest by the Sea of Gods are given a bed and a bowl and asked nothing, for the keepers say a traveller who has come so far has already answered every question worth asking.", "Saying of the sanctuaries of Tor Luni", "The Noon Pilgrimage (P, belief); Tor Luni (P name, Lands of the Sun dossier)"],
[128, DA, 'Dark Lands', 'proverb', 0, "Goldoroth was once many holds under many chiefs, and now it is one hold under one chief with a great many graves, which the warking's heralds like to call unity.", "Saying of the Dondor marches", "Goldoroth's uniting (P date)"],
[129, DA, 'Dark Lands', 'proverb', 0, "Dondor has held the line against Goldoroth for three hundred years, and in Notbuton they talk about it the way other towns talk about the weather.", "Saying of Notbuton", "Dondor and Goldoroth (W rivalry, P dates)"],
[130, DA, 'Dark Lands', 'proverb', 0, "Bordon, Dreson and Dulundur answer to nobody, and they have done it for so long that nobody has troubled to ask them anything in living memory.", "Saying of the Dark Lands", "Independent Dark Lands holds (E)"],
[131, DA, 'Dark Lands', 'woodsfolk', 0, "Smash is king of the Troll Forest and of nothing beyond it, and he says so himself, but anybody who wants to argue the point about the forest is welcome to walk in and try.", "Saying of the Bordon woodcutters", "Troll Forest (E); Smash rules his own realm only (E, owner 24 October 2026)"],
[132, DA, 'Dark Lands', 'priest', 0, "The fire-speakers of Cocanoor read the smoke above the Fire-Mountain every morning, and on the mornings when it drifts south they say nothing at all, which the clans have learned to take badly.", "Saying of the Volcano Clans", "Goldoroth's fire-speakers (P)"],
[133, DA, 'Dark Lands', 'proverb', 0, "Strangers from the south come up the coast with good iron and better promises, and the old men of the free holds tell their sons to take the iron and leave the promises on the beach.", "Saying of the free holds", "Volgan's envoys court the Dark Lands (E, Campaign of 4A 1748)"],
[134, EM, 'Ember Lands', 'soldier', 0, "Keep the beacon on the southern pass burning, my son, because Volgan was quiet once before, for a very long time, and the quiet did not last.", "Saying of the watch of Mirolon", "Volgan's banishment and return (E)"],
[135, EM, 'Ember Lands', 'proverb', 0, "Mirolon was the first kingdom Volgan ever took, and every warden of Mirolon means it to be the last he ever tries for.", "Saying of the passes", "Volgan's First Age conquest of Mirolon (E)"],
[136, EM, 'Ember Lands', 'dark power', 0, "The kingdoms of men always divide in the end, the old song has Volgan say, and I have only to wait for them to do it, which I have never minded.", "Words that Mirolon's old songs give to Volgan", "Volgan's patience (P voice)"],
[137, EM, 'Ember Lands', 'peasant', 0, "We bury our dead quickly down here, and deep, with salt in the grave, and we say nothing over them about Zol or about the master of the island, in case either of them is listening.", "Saying of the Ember Lands freeholders", "The Mourning Customs of the Ember Lands (P, world bible section 4)"],
[138, EM, 'Ember Lands', 'dark power', 0, "The lords of the Nether keep every bargain to the letter, and that, the old men of Herez say, is the very part that the men who bargain with them forget to fear.", "Saying of the Herez marches", "The King of Demons' pacts bind the living (E, owner 24 October 2026); the Nether (E)"],
[139, ZO, "Zol's Mistake", 'seafarer', 1, "My father sailed past the black shore once in his life, and all he would ever say of it was that nothing grows there and something walks there, and that he would thank me not to ask again.", "Saying of the Leren harbours", "Roamed by the dead (E)"],
[140, ZO, "Zol's Mistake", 'elf', 0, "From the brown hills of Herrodon you can see the black shore on a clear day, and the elves who live there have built every house in the hills with its door facing the other way.", "Saying of Herrodon", "Herrodon's highland against the Kusmeel and the black north (P, Magical Lands dossier); Zol's Mistake (E)"],
[141, ZO, "Zol's Mistake", 'scholar', 0, "Ask a scholar of Parim why the black north is called Zol's Mistake and he will lecture you on everything but the answer, because nobody knows it, and no scholar has yet gone to look.", "Jest of the students of Parim", "The name is unexplained (E; mystery V2)"],
[142, ZO, "Zol's Mistake", 'proverb', 0, "The old men of the north coast say a sword that kills a man will only annoy the dead of the Mistake, so every village there keeps a Name-Reader of Gaelor as well as a smith, and pays him better.", "Saying of the northern coasts", "Ordinary weapons cannot end Zol's dead (E); Gaelor's Name-Readers (P)"],
[143, EA, 'East Lands', 'priest', 0, "The wells of Woqood face the black sea, and the well-wives there pour the first water of the year back into the sand facing south, so that nothing out on the water thinks it was meant for it.", "Custom of the well-wives of Woqood", "Woqood, a north-coast kingdom whose wells face the Kusmeel (world bible); the Well-Oath (P)"],
[144, EA, 'East Lands', 'trader', 0, "Noris and Stabilo have fought over every road in the East for as long as anyone remembers, and the little courts along those roads have grown fat on selling water to both.", "Saying of the salt road", "Noris and Stabilo rivalry (W)"],
[145, SO, 'South Lands', 'trader', 0, "In the Noris desert a stranger's map is a kind gift, but a rider's memory of the wells is a fortune, and no rider in his right mind has ever sold it.", "Saying of the camel riders of Noris", "Noris camel warriors (E)"],
[146, EA, 'East Lands', 'trader', 0, "In Postondoroth they weigh gold, salt and promises on the same scale, and somehow it is only ever the promises that come up light.", "Market saying of Postondoroth", "Stabilo's trade (P)"],
[147, EA, 'East Lands', 'trader', 0, "A caravan master carries three sets of scales, one for buying, one for selling and one for the customs house, and he trusts none of them as far as he trusts his camels.", "Saying of the caravan masters", "East Lands rich and divided (E)"],
[148, EA, 'East Lands', 'trader', 0, "Naamis, Drak, Alerhia and Miaed are four courts with forty quarrels between them and one road to share, so a wise traveller learns four sets of manners before he sets out.", "Caravan saying of the East Lands", "East Lands courts (W, map); Naamis, former label Gondolin (P name, East Lands dossier)"],
[149, EA, 'East Lands', 'ruler', 0, "The old charts of Aenor call us Easterlings, as though we were something that happened to the east of them, but our kings were crowned beside the rift long before the first chart was drawn.", "Saying of the river kingdoms of the East", "Easterlings in First Age usage (E); the river kingdoms (P)"],
];

// Tips: copy as they are, except those whose language breaks the voice guide.
const TIP_FIX = {
  154: "Aoaz counts twelve months, each named for one of the twelve main New Gods, from Glernaen to Naisa. The campaign opens on 1 Lumae, 4A 1748, the day of the Lamp-Lighting and the first day of spring.",
  158: "Declare war while the long peace holds and you are branded a breaker of the peace: calm and the will to war fall, and the Gathering Dark rises.",
  168: "Rangers, hill companies, sea soldiers and temple wardens are the picked troops of Aoaz, and few realms can field many of them.",
  170: "The Great Wall of Aenor is a range of mountains, and forts hold its passes from the Organ Mountains past Lunhrim to Kingson. The forts need upkeep, and every breach matters.",
  172: "The seas around the Ember Lands are wracked by storms. Without storm rigging, a fleet loses ships there before it ever meets an enemy.",
  185: "Playing Volgan's Dominion? Your grave hosts fray far from the Ember Lands. Necromancers slow the decay, and patience serves you better than haste.",
  186: "Playing Zol's Mistake? The black north gathers its strength slowly, and strength left untended can ebb away. Tend it with patience, and let the dead do the walking.",
  189: "Every realm has its own Path of the Realm, and some of its branches open only as the age moves on, so look again whenever the world changes.",
  152: "Great powers have their own panel, which opens from the small sigil at the end of the Aoaz bar. The panels show you the state of things; the decisions are where you act.",
};

const banned = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools/content/data/banned_words.json'), 'utf8'));
const rx = banned.rules.map(r => ({ id: r.id, sev: r.severity, re: new RegExp(`(?<![A-Za-z0-9'])(?:${r.pattern})(?![A-Za-z0-9'])`, r.caseSensitive ? 'u' : 'iu') }));
const extra = /\b(Ocean|Erdae|Edvoid|Kusven|Triton|Dead Lands|Gunwaith|Lerenwaith|Asgard|Isengard|Titanos|Hengyang|Gondolin|Hiloron|Thaw|Highsun|Deepwinter|Harvest|metres?|Einendil|-waith|arguably|in many ways|perhaps)\b/i;

const out = [];
const problems = [];
const byKey = new Map(src.tips.map(t => [t.key, t]));
const seen = new Set();
for (const [i, group, region, speaker, sea, text, attribution, basis] of Q) {
  const key = `LOADING_TIP_${i}`;
  if (seen.has(i)) problems.push(`dup ${i}`); seen.add(i);
  const old = byKey.get(key);
  if (!old || old.kind !== 'quote') problems.push(`not a quote ${key}`);
  if (text.length >= 220) problems.push(`${key} text ${text.length}`);
  if ((text.length + attribution.length + 3) >= 300) problems.push(`${key} string too long`);
  if (/[^\x20-\x7e]/.test(text + attribution)) problems.push(`${key} non-ascii`);
  if (/["$\[\]]/.test(text + attribution)) problems.push(`${key} forbidden char`);
  for (const r of rx) if (r.re.test(text) || r.re.test(attribution)) problems.push(`${key} banned ${r.id} (${r.sev})`);
  if (extra.test(text) || extra.test(attribution)) problems.push(`${key} extra ${(text + ' ' + attribution).match(extra)[0]}`);
  out.push({ key, kind: 'quote', group, text, attribution, basis, status: 'proposed', rewrite: '2026-10-24', _region: region, _speaker: speaker, _sea: sea });
}
for (let i = 0; i < 150; i++) if (!seen.has(i)) problems.push(`missing ${i}`);
out.sort((a, b) => Number(a.key.split('_')[2]) - Number(b.key.split('_')[2]));

const tips = src.tips.filter(t => t.kind === 'tip').map(t => {
  const n = Number(t.key.split('_')[2]);
  if (TIP_FIX[n]) {
    const text = TIP_FIX[n];
    if (text.length >= 220) problems.push(`tip ${n} ${text.length}`);
    for (const r of rx) if (r.re.test(text)) problems.push(`tip ${n} banned ${r.id}`);
    return { ...t, text, status: 'proposed', rewrite: '2026-10-24' };
  }
  for (const r of rx) if (r.re.test(t.text)) problems.push(`tip ${n} (unchanged) banned ${r.id}`);
  return { ...t };
});

const doc = {
  source: 'tools/content/data/loading_tips.json',
  guide: 'docs/specs/02_lore/09_voice_and_style.md',
  decision: 'K33, owner, 24 October 2026: quotes rewritten in a natural period voice, fewer fishing and sea quotes, spread across all regions',
  note: 'Proposed replacement for the quote and tip records of loading_tips.json, key for key and in key order. Quotes LOADING_TIP_0..149 ship as "<text>\\n- <attribution>"; tips LOADING_TIP_150..189 ship as "\u00a7YCounsel:\u00a7! <text>". Records with "rewrite" changed on that date; tips without it are copied unchanged. Every quote text and attribution is proposed.',
  format: src.format,
  tips: [...out.map(({ _region, _speaker, _sea, ...r }) => r), ...tips],
};

const outPath = path.join(ROOT, 'docs/design/text/loading_quotes_v2.json');
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, JSON.stringify(doc, null, 2) + '\n', 'utf8');

const count = (f) => out.reduce((m, r) => (m[r[f]] = (m[r[f]] || 0) + 1, m), {});
console.log('problems', problems);
console.log('quotes', out.length, 'tips', tips.length, 'tips changed', Object.keys(TIP_FIX).length);
console.log('sea', out.filter(r => r._sea).map(r => r.key));
console.log('region', count('_region'));
console.log('speaker', count('_speaker'));
console.log('maxlen', Math.max(...out.map(r => r.text.length)));
